"""Algorithm A: End classification of a two-point remainder.

Given a compactification of the real line presented by neighbourhood bases at
its remainder points, decide for each remainder point whether it is isolated,
the positive end, the negative end, or a merged end absorbing both rays; then
identify the model.

By the classification theorem, the signature determines the topology:
(positive, negative) is the end compactification, (negative, positive) is its
flip, and anything containing an isolated or merged remainder point is exotic.
"""

from __future__ import annotations

from typing import Callable, Sequence

Point = tuple[str, float]  # ("fin", x) or ("+oo", 0.0) / ("-oo", 0.0) / ("PHI", 0.0)

MembershipOracle = Callable[[str, float, Point], bool]
IsolationOracle = Callable[[str], bool]


def absorbs_ray(member: MembershipOracle, isolated: IsolationOracle,
                point: str, thresholds: Sequence[float], sign: float) -> bool:
    """Test whether every basic neighbourhood of ``point`` meets the ray of the
    given sign arbitrarily far out."""
    if isolated(point):
        return False
    return all(member(point, b, ("fin", sign * (abs(b) + b + 1.0))) for b in thresholds)


def classify_point(member: MembershipOracle, isolated: IsolationOracle,
                   point: str, thresholds: Sequence[float]) -> str:
    """Return one of: 'isolated', 'positive end', 'negative end', 'merged end',
    'limit point, not an end'."""
    if isolated(point):
        return "isolated"
    pos = absorbs_ray(member, isolated, point, thresholds, +1.0)
    neg = absorbs_ray(member, isolated, point, thresholds, -1.0)
    if pos and neg:
        return "merged end"
    if pos:
        return "positive end"
    if neg:
        return "negative end"
    return "limit point, not an end"


def identify_model(member: MembershipOracle, isolated: IsolationOracle,
                   thresholds: Sequence[float]) -> tuple[dict[str, str], str]:
    """Classify all three exceptional points and name the resulting model."""
    signature = {p: classify_point(member, isolated, p, thresholds)
                 for p in ("+oo", "-oo", "PHI")}
    if signature["+oo"] == "positive end" and signature["-oo"] == "negative end":
        name = "end compactification (natural topology)"
    elif signature["+oo"] == "negative end" and signature["-oo"] == "positive end":
        name = "flip of the end compactification"
    elif "merged end" in signature.values():
        name = "exotic: the two ends are identified (circle model)"
    else:
        name = "not a two-ended compactification"
    return signature, name


if __name__ == "__main__":
    def natural(a: str, b: float, p: Point) -> bool:
        if p[0] != "fin":
            return p[0] == a
        return p[1] > b if a == "+oo" else (p[1] < -b if a == "-oo" else False)

    def circle(a: str, b: float, p: Point) -> bool:
        if p[0] != "fin":
            return p[0] == a
        return abs(p[1]) > b if a == "-oo" else False

    ths = [0.0, 1.0, 1e3, 1e9]
    print(identify_model(natural, lambda a: a == "PHI", ths))
    print(identify_model(circle, lambda a: a in ("PHI", "+oo"), ths))

