INPUT   U, V: membership predicates for two disjoint open sets,
              U containing the first infinity, V the second
        grid:        increasing finite list of candidate radii
        probes:      increasing finite list of offsets
OUTPUT  the core radius M, the ray assignment, and a split/merged verdict

function CORE_RADIUS():
    for M in ascending(grid):
        if for all s in probes:
               (U(fin(M+s)) or V(fin(M+s))) and (U(fin(-M-s)) or V(fin(-M-s))):
            return M
    return FAIL                       # no radius covers both rays

function WHERE(x):
    if U(fin(x)) and not V(fin(x)):   return 'U'
    if V(fin(x)) and not U(fin(x)):   return 'V'
    if U(fin(x)) and V(fin(x)):       return 'NOT DISJOINT'
    return 'uncovered'

function RAY_ASSIGNMENT(M):
    return WHERE(M + 100), WHERE(-M - 100)

function ENDS_ARE_SPLIT(M):
    (p, n) <- RAY_ASSIGNMENT(M)
    return p != n and 'uncovered' not in {p, n}

function CONSTANCY_CHECK(M, S):
    base <- U(fin(M+1))
    return for all k < S: U(fin(M + 1 + 10k)) = base

