"""Algorithm B: Compact core radius and ray assignment.

The computational shadow of the ray-separation lemma. Given disjoint open sets
U around +oo and V around -oo, the part of the space they fail to cover is
compact and lies inside the line, hence is bounded; the algorithm finds a
radius M beyond which the two rays are entirely covered, and reports which
separator receives which ray. Connectedness of each ray guarantees the
assignment is constant, and the end property guarantees the two rays are
assigned to different separators in any model with two honest ends.
"""

from __future__ import annotations

from typing import Callable, Optional, Sequence

Point = tuple[str, float]
Predicate = Callable[[Point], bool]


def covered(U: Predicate, V: Predicate, x: float) -> bool:
    return U(("fin", x)) or V(("fin", x))


def core_radius(U: Predicate, V: Predicate, grid: Sequence[float],
                probe_scales: Sequence[float] = (1.0, 10.0, 1e3, 1e9)) -> Optional[float]:
    """Least M on the grid such that both rays (M, oo) and (-oo, -M) are covered."""
    for M in sorted(grid):
        ok = all(covered(U, V, M + s) and covered(U, V, -M - s) for s in probe_scales)
        if ok:
            return M
    return None


def ray_assignment(U: Predicate, V: Predicate, M: float) -> tuple[str, str]:
    """Report which separator receives the positive and the negative ray."""
    def where(x: float) -> str:
        p: Point = ("fin", x)
        if U(p) and not V(p):
            return "U (around +oo)"
        if V(p) and not U(p):
            return "V (around -oo)"
        if U(p) and V(p):
            return "both (separators are not disjoint!)"
        return "uncovered"
    return where(M + 100.0), where(-M - 100.0)


def ends_are_split(U: Predicate, V: Predicate, M: float) -> bool:
    """True when the two rays go to different separators: the signature of a
    genuine two-point remainder."""
    pos, neg = ray_assignment(U, V, M)
    return pos != neg and "uncovered" not in (pos, neg)


def constancy_check(U: Predicate, V: Predicate, M: float,
                    samples: int = 200) -> bool:
    """Verify numerically that the assignment of the positive ray does not
    oscillate: the discrete trace of connectedness."""
    base = U(("fin", M + 1.0))
    return all(U(("fin", M + 1.0 + 10.0 * k)) == base for k in range(samples))


if __name__ == "__main__":
    b = 3.0

    def U_nat(p: Point) -> bool:
        return p[0] == "+oo" or (p[0] == "fin" and p[1] > b)

    def V_nat(p: Point) -> bool:
        return p[0] == "-oo" or (p[0] == "fin" and p[1] < -b)

    M = core_radius(U_nat, V_nat, [0.0, 1.0, 2.0, 5.0, 10.0])
    print("core radius:", M)
    print("assignment :", ray_assignment(U_nat, V_nat, M or 0.0))
    print("split ends :", ends_are_split(U_nat, V_nat, M or 0.0))
    print("no oscillation:", constancy_check(U_nat, V_nat, M or 0.0))

algorithms.pseudocode:
INPUT   member(a, b, p), isolated(a): the model's neighbourhood oracles
        thresholds: finite list of thresholds; depth: sampling depth
OUTPUT  the unique repairing value, or NONE

function TAIL_LIMIT(values):
    for a in {+oo, -oo, PHI}:
        if isolated(a): continue         # nothing finite converges to it
        tail <- second half of values
        if for all b in thresholds, for all x in tail: member(a, b, fin(x)):
            return a
    return NONE

function ONE_SIDED_LIMITS():
    right <- [ 10^k  : k = 1 .. depth ]   # the values 1/y for y = +10^-k
    left  <- [ -10^k : k = 1 .. depth ]   # the values 1/y for y = -10^-k
    return TAIL_LIMIT(right), TAIL_LIMIT(left)

function REPAIRING_VALUE():
    (r, l) <- ONE_SIDED_LIMITS()
    if r != NONE and r = l: return r      # unique repair, by Hausdorffness
    return NONE                           # the guard at zero is necessary
